class Solution {
public:
    string removeTrailingZeros(string num) {
        while (!num.empty() && num.back() == '0') {
            num.pop_back();
        }
        return num;
    }
};

class Solution {
    public String removeTrailingZeros(String num) {
        int i = num.length() - 1;
        while (i >= 0 && num.charAt(i) == '0') {
            i--;
        }
        return num.substring(0, i + 1);
    }
}
